import { writeOffList, putWriteUpdate } from '@/api/order';
export default {
    name: 'orderRecord',
    props: {
        orderNumId: String
    },
    data () {
        return {
            modals: false,
            loading: false,
            writeOffData: [],
            writeOffItem: [],
            columns: [{
                type: "selection",
                width: 50,
                align: "center",
            },
                {
                    title: "商品信息",
                    slot: "image",
                    align: "center",
                    minWidth: 150,
                },
                {
                    title: "规格",
                    slot: "value",
                    align: "center",
                    minWidth: 90,
                },
                {
                    title: "商品售价",
                    slot: "sellPrice",
                    align: "center",
                    minWidth: 60,
                },
                {
                    title: "商品优惠价",
                    slot: "price",
                    align: "center",
                    minWidth: 60,
                },
                {
                    title: "状态",
                    slot: "writeOff",
                    align: "center",
                    minWidth: 30,
                },
                {
                    title: "总数",
                    slot: "cartNum",
                    align: "center",
                    minWidth: 30,
                },
                {
                    title: "待核销数量",
                    key: "surplus_num",
                    align: "center",
                    minWidth: 130,
                    render: (h, params) => {
                        return h("div", [
                            h("InputNumber", {
                                props: {
                                    min: 1,
                                    max: params.row.numShow,
                                    value: params.row.surplus_num || 1,
                                    disabled: params.row.is_writeoff?true:false
                                },
                                on: {
                                    "on-change": (e) => {
                                        params.row.surplus_num = e || 1;
                                        if(this.writeOffItem.length){
                                            this.writeOffItem.forEach((item)=>{
                                                if(item.id == params.row.id){
                                                    item.surplus_num = params.row.surplus_num
                                                }else{
                                                    this.writeOffItem.push(params.row)
                                                }
                                            })
                                        }else{
                                            this.writeOffItem.push(params.row)
                                        }
                                        this.selectData.forEach((v, index) => {
                                            if (v.cart_id === params.row.cart_id) {
                                                this.selectData.splice(index, 1, params
                                                    .row);
                                            }
                                        });
                                    },
                                },
                            }),
                        ]);
                    },
                }
            ],
            selectData:[]
        }
    },
    methods: {
        cancel(){
            this.$refs.selection.selectAll(false);
        },
        selectOne(data) {
            data.forEach((item)=>{
                this.writeOffItem.forEach((j)=>{
                    if(item.id == j.id){
                        item.surplus_num = j.surplus_num
                    }
                })
            })
            this.selectData = data;
        },
        // 核销列表
        getWriteOff(data){
            writeOffList(data).then(res=>{
                let data = res.data.cart_info;
                data.forEach((item)=>{
                    item.numShow = item.surplus_num
                    if(item.is_writeoff){
                        item._disabled = true
                    }
                })
                this.writeOffData = data;
            }).catch(err=>{
                this.$Message.error(res.msg);
            })
        },
        submitWriteOff(){
            if(!this.selectData.length){
                return this.$Message.error('请选择要核销的商品');
            }
            let cartIds = []
            this.selectData.forEach((v) => {
                cartIds.push({
                    cart_id: v.cart_id,
                    cart_num: v.surplus_num,
                });
            });
            console.log('rrrrr',cartIds);
            console.log('rrrryyy',this.orderNumId);
            putWriteUpdate(this.orderNumId,{'cart_ids':cartIds}).then(res=>{
                this.$Message.success(res.msg);
                this.modals = false;
                this.$refs.selection.selectAll(false);
                this.$emit("submitSuccess");
            }).catch(err=>{
                this.$Message.error(err.msg);
            })
        }
    }
}
